    ]

    outputs = [Output(display_name="Agent Prompt", name="agent_prompt", method="build_prompt")]

    def _to_text(self, value) -> str:
        if value is None:
            return ""
        text = getattr(value, "text", None)
        if text is not None:
            return str(text)
        value = getattr(value, "value", value)
        return str(value or "")

    def _message_files(self, value):
        if value is None:
            return []
        files = getattr(value, "files", None)
        data = getattr(value, "data", None)
        if files is None and isinstance(data, dict):
            files = data.get("files") or data.get("file") or data.get("attachments")
        if not files:
            return []
        return files if isinstance(files, list) else [files]

    def _candidate_strings(self, item):
        vals = []
        if isinstance(item, str):
            vals.append(item)
        if isinstance(item, dict):
            for key in ["path", "file_path", "temp_file", "filepath", "url", "name", "filename", "display_name"]:
                if item.get(key):
                    vals.append(str(item[key]))
        for attr in ["path", "file_path", "temp_file", "filepath", "url", "name", "filename", "display_name"]:
            try:
                value = getattr(item, attr, None)
                if value:
                    vals.append(str(value))
            except Exception:
                pass
        return vals

    def _embedded_bytes_or_text(self, item):
        import base64

        keys = ["bytes", "content", "contents", "data", "file", "value", "text"]
        vals = [item.get(k) for k in keys] if isinstance(item, dict) else []
        if not isinstance(item, dict):
            for key in keys:
                try:
                    vals.append(getattr(item, key, None))
                except Exception:
                    pass
        for val in vals:
            if isinstance(val, (bytes, bytearray)):
                return bytes(val), ""
            if isinstance(val, str) and len(val.strip()) > 20:
                raw = val.split(",", 1)[1] if val.startswith("data:") and "," in val else val
                try:
                    decoded = base64.b64decode(raw, validate=True)
                    if decoded:
                        return decoded, ""
                except Exception:
                    pass
                return b"", val
        return b"", ""

    def _override_items(self):
        lines = [x.strip().strip('"') for x in self._to_text(self.file_path_override).splitlines()]
        return [x for x in lines if x]

    def _resolve_path(self, item):
        import os
        import tempfile
        from pathlib import Path

        for cand in self._candidate_strings(item):
            if cand and os.path.exists(cand):
                return cand, ""
        basenames = [os.path.basename(c) for c in self._candidate_strings(item) if c]
        basenames = [b for b in basenames if b and "." in b]
        roots = [r for r in [tempfile.gettempdir(), os.getcwd(), str(Path.home())] if r and os.path.exists(r)]
        for base in basenames[:5]:
            checked = 0
            for root in roots:
                for dirpath, _, filenames in os.walk(root):
                    checked += 1
                    if checked > 2500:
                        break
                    if base in filenames:
                        return os.path.join(dirpath, base), "resolved by basename search"
                if checked > 2500:
                    break
        return "", "No accessible file path found. Add exact path in File Path Override, paste text into Manual Context / OCR Paste, or upload a text-convertible file."

    def _decode_text_bytes(self, raw, max_chars):
        for enc in ["utf-8", "utf-16", "latin-1"]:
            try:
                return raw.decode(enc, errors="ignore")[:max_chars]
            except Exception:
                pass
        return raw.decode("utf-8", errors="ignore")[:max_chars]

    def _clean_text(self, text):
        import re

        text = text or ""
        text = text.replace("\x00", " ")
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

    def _strip_markup(self, text):
        import re
        import html

        text = re.sub(r"<script[\s\S]*?</script>", " ", text, flags=re.I)
        text = re.sub(r"<style[\s\S]*?</style>", " ", text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        return self._clean_text(html.unescape(text))

    def _read_text_path(self, path, max_chars):
        with open(path, "rb") as f:
            return self._decode_text_bytes(f.read(max_chars * 2), max_chars)

    def _read_pdf(self, path, max_chars):
        for module_name in ["pypdf", "PyPDF2"]:
            try:
                mod = __import__(module_name)
                reader = getattr(mod, "PdfReader")(path)
                meta = getattr(reader, "metadata", None)
                chunks = []
                for page_index, page in enumerate(reader.pages[:80], start=1):
                    text = page.extract_text() or ""
                    if text.strip():
                        chunks.append(f"[page {page_index}]\n{text}")
                    if sum(len(c) for c in chunks) >= max_chars:
                        break
                joined = self._clean_text("\n\n".join(chunks))
                if joined:
                    meta_text = f"PDF pages: {len(reader.pages)}"
                    if meta:
                        meta_text += f"; metadata: {meta}"
                    return joined[:max_chars], meta_text, []
            except Exception:
                pass
        ocr_text, ocr_note = self._ocr_path(path, max_chars)
        if ocr_text:
            return ocr_text, "PDF OCR fallback used", [ocr_note]
        return "", "PDF extraction failed", ["PDF may be scanned/image-based, locked, or parser libraries are unavailable. OCR library not available or failed."]

    def _read_docx(self, path, max_chars):
        try:
            import zipfile

            parts = []
            with zipfile.ZipFile(path) as z:
                for name in z.namelist():
                    if name.startswith("word/") and name.endswith(".xml"):
                        parts.append(self._strip_markup(z.read(name).decode("utf-8", errors="ignore")))
            return self._clean_text("\n".join(parts))[:max_chars], "DOCX XML extracted", []
        except Exception as exc:
            return "", "DOCX extraction failed", [f"{type(exc).__name__}: {exc}"]

    def _read_xlsx(self, path, max_chars):
        try:
            import re
            import zipfile

            rows = []
            with zipfile.ZipFile(path) as z:
                shared = []
                if "xl/sharedStrings.xml" in z.namelist():
                    shared = re.findall(r"<t[^>]*>(.*?)</t>", z.read("xl/sharedStrings.xml").decode("utf-8", errors="ignore"))
                for sheet in [n for n in z.namelist() if n.startswith("xl/worksheets/sheet") and n.endswith(".xml")][:10]:
                    xml = z.read(sheet).decode("utf-8", errors="ignore")
                    vals = re.findall(r"<v>(.*?)</v>", xml)
                    cooked = []
                    for val in vals[:1000]:
                        try:
                            idx = int(val)
                            cooked.append(shared[idx] if 0 <= idx < len(shared) else val)
                        except Exception:
                            cooked.append(val)
                    rows.append(f"[{sheet}]\n" + ", ".join(cooked))
            return self._clean_text("\n\n".join(rows))[:max_chars], "XLSX worksheet values extracted", []
        except Exception as exc:
            return "", "XLSX extraction failed", [f"{type(exc).__name__}: {exc}"]

    def _read_pptx(self, path, max_chars):
        try:
            import zipfile

            slides = []
            with zipfile.ZipFile(path) as z:
                for name in [n for n in z.namelist() if n.startswith("ppt/slides/slide") and n.endswith(".xml")][:80]:
                    slides.append(f"[{name}]\n" + self._strip_markup(z.read(name).decode("utf-8", errors="ignore")))
            return self._clean_text("\n\n".join(slides))[:max_chars], "PPTX slide XML extracted", []
        except Exception as exc:
            return "", "PPTX extraction failed", [f"{type(exc).__name__}: {exc}"]

    def _read_zip(self, path, max_chars):
        import os
        import tempfile
        import zipfile

        if not self.enable_zip_extract:
            return "", "ZIP extract disabled", ["Enable ZIP Auto Extract is OFF."]
        blocks, notes = [], []
        budget_left = max_chars
        try:
            with zipfile.ZipFile(path) as z:
                names = [n for n in z.namelist() if not n.endswith("/")][:25]
                with tempfile.TemporaryDirectory() as td:
                    for name in names:
                        if budget_left <= 500:
                            break
                        safe = os.path.basename(name)
                        if not safe:
                            continue
                        out = os.path.join(td, safe)
                        with open(out, "wb") as f:
                            f.write(z.read(name))
                        res = self._read_path(out, min(4000, budget_left))
                        if res["text"]:
                            blocks.append(f"[ZIP item: {name}]\n{res['text']}")
                            budget_left -= len(res["text"])
                        notes.extend(res["recoveries"])
            return self._clean_text("\n\n".join(blocks))[:max_chars], "ZIP auto-extracted", notes
        except Exception as exc:
            return "", "ZIP extraction failed", [f"{type(exc).__name__}: {exc}"]

    def _ocr_path(self, path, max_chars):
        if not self.enable_ocr:
            return "", "OCR disabled."
        try:
            import pytesseract
            from PIL import Image

            text = pytesseract.image_to_string(Image.open(path))
            return self._clean_text(text)[:max_chars], "OCR used via pytesseract/Pillow."
        except Exception as exc:
            return "", f"OCR unavailable or failed: {type(exc).__name__}: {exc}"

    def _read_path(self, path, max_chars):
        import os
        import json

        ext = os.path.splitext(path)[1].lower()
        recoveries = []
        text, method = "", ""
        if ext == ".pdf":
            text, method, recoveries = self._read_pdf(path, max_chars)
        elif ext == ".docx":
            text, method, recoveries = self._read_docx(path, max_chars)
        elif ext in [".xlsx", ".xlsm"]:
            text, method, recoveries = self._read_xlsx(path, max_chars)
        elif ext == ".pptx":
            text, method, recoveries = self._read_pptx(path, max_chars)
        elif ext == ".zip":
            text, method, recoveries = self._read_zip(path, max_chars)
        elif ext in [".png", ".jpg", ".jpeg", ".webp", ".bmp", ".tif", ".tiff"]:
            text, method = self._ocr_path(path, max_chars)
            recoveries = [] if text else [method, "Install Pillow + pytesseract and system Tesseract OCR, or paste OCR text manually."]
        elif ext in [".json"]:
            try:
                parsed = json.loads(self._read_text_path(path, max_chars))
                text, method = json.dumps(parsed, indent=2, ensure_ascii=False)[:max_chars], "JSON parsed"
            except Exception:
                text, method = self._read_text_path(path, max_chars), "JSON fallback as text"
        elif ext in [".html", ".htm", ".xml"]:
            text, method = self._strip_markup(self._read_text_path(path, max_chars)), "markup stripped"
        else:
            text, method = self._read_text_path(path, max_chars), "plain text compatible"
        return {"path": path, "text": self._clean_text(text)[:max_chars], "method": method, "recoveries": recoveries}

    def _read_item(self, item, max_chars):
        raw, embedded_text = self._embedded_bytes_or_text(item)
        if embedded_text:
            return {"path": "embedded message text", "text": self._clean_text(embedded_text)[:max_chars], "method": "embedded text", "recoveries": []}
        if raw:
            text = self._decode_text_bytes(raw, max_chars)
            if len(text.strip()) > 50:
                return {"path": "embedded bytes", "text": self._clean_text(text)[:max_chars], "method": "embedded bytes decoded as text", "recoveries": []}
        path, note = self._resolve_path(item)
        if not path:
            return {"path": str(item), "text": "", "method": "path resolution failed", "recoveries": [note]}
        return self._read_path(path, max_chars)

    def _language_hint(self, text):
        low = (text or "").lower()
        id_hits = sum(w in low for w in ["yang", "dan", "adalah", "untuk", "dengan", "dari", "pada"])
        en_hits = sum(w in low for w in ["the", "and", "is", "for", "with", "from", "this"])
        if id_hits > en_hits:
            return "Indonesian likely"
        if en_hits > id_hits:
            return "English likely"
        return "Mixed/unknown"

    def _structure_report(self, text):
        import re

        lines = [x.strip() for x in (text or "").splitlines() if x.strip()]
        headings = [x for x in lines if len(x) < 90 and (x.isupper() or re.match(r"^\d+(\.\d+)*\s+\S+", x))]
        tables = [x for x in lines if x.count(",") >= 3 or x.count("\t") >= 2 or x.count("|") >= 2]
        equations = [x for x in lines if re.search(r"=|\\bsum\\b|\\bmean\\b|\\bvariance\\b|\\bregression\\b|\\by\\s*=", x, re.I)]
        refs = [x for x in lines if re.search(r"doi|references|bibliography|daftar pustaka|et al\\.|https?://", x, re.I)]
        figures = [x for x in lines if re.search(r"figure|fig\\.|gambar|tabel|table|chart|grafik", x, re.I)]
        return {
            "headings": headings[:12],
            "tables": tables[:8],
            "equations": equations[:8],
            "references": refs[:8],
            "figures": figures[:8],
        }

    def _summary(self, text, limit=1200):
        sentences = []
        for part in (text or "").replace("\n", " ").split("."):
            part = part.strip()
            if len(part) > 35:
                sentences.append(part + ".")
            if len(" ".join(sentences)) >= limit:
                break
        return " ".join(sentences)[:limit] if sentences else (text or "")[:limit]

    def _line_type(self, line):
        import re

        s = (line or "").strip()
        if not s:
            return "blank"
        low = s.lower()
        if re.match(r"^(\d+(\.\d+)*|[ivxlcdm]+\.?)\s+[\w(]", low) or (len(s) <= 90 and s.isupper()):
            return "heading"
        if s.count("|") >= 2 or s.count("\t") >= 2 or s.count(",") >= 5:
            return "table"
        if re.search(r"(^|[^a-z])(y|x|r|p|z|t|f)\s*=|=|∑|√|\bsum\b|\bmean\b|\bvariance\b|\bstdev\b", s, re.I):
            return "equation"
        if re.search(r"^(references|bibliography|daftar pustaka)\b|doi:|https?://|et al\.", low):
            return "reference"
        if re.search(r"^(figure|fig\.|gambar|table|tabel|chart|grafik)\b", low):
            return "figure"
        return "paragraph"

    def _semantic_signature(self, text):
        toks = self._tokens(text)
        if not toks:
            return set()
        grams = set(toks)
        for i in range(len(toks) - 1):
            grams.add(toks[i] + "_" + toks[i + 1])
        return grams

    def _source_metadata(self, chunk):
        text = (chunk.get("text") or "").lower()
        heading = (chunk.get("heading_path") or "").lower()
        combined = text + " " + heading
        credibility = "Unclassified"
        source_rank = 0.35
        if any(x in combined for x in ["bps.go.id", "bi.go.id", "ojk.go.id", "worldbank.org", "imf.org", "oecd.org", "who.int", ".go.id", ".gov", ".edu", ".ac.id"]):
            credibility, source_rank = "High", 1.0
        elif any(x in combined for x in ["nature.com", "sciencedirect.com", "crossref.org", "openai.com", "tensorflow.org", "pytorch.org", "scikit-learn.org"]):
            credibility, source_rank = "High/Technical", 0.9
        elif any(x in combined for x in ["ourworldindata.org", "arxiv.org", "semanticscholar.org", "github.com", "kaggle.com", "oeis.org"]):
            credibility, source_rank = "Medium-High/Medium", 0.72
        elif "wikipedia.org" in combined:
            credibility, source_rank = "Low-priority fallback", 0.42
        return {"credibility": credibility, "source_rank": source_rank}

    def _metadata_match(self, chunk):
        filters = [x.strip().lower() for x in self._to_text(self.metadata_filter).replace(",", "\n").splitlines() if x.strip()]
        if not filters:
            return True, 0.0
        hay = ((chunk.get("heading_path") or "") + "\n" + (chunk.get("type") or "") + "\n" + (chunk.get("text") or "")).lower()
        hits = sum(1 for f in filters if f in hay)
        return hits > 0, min(1.0, hits / max(1, len(filters)))

    def _vectorize(self, text, dims=64):
        import math

        vec = [0.0] * dims
        toks = self._tokens(text)
        if not toks:
            return vec
        for tok in toks:
            idx = abs(hash(tok)) % dims
            vec[idx] += 1.0
        norm = math.sqrt(sum(v * v for v in vec)) or 1.0
        return [v / norm for v in vec]

    def _cosine(self, a, b):
        return sum(x * y for x, y in zip(a, b))

    def _adaptive_chunks(self, text, fallback_size):
        import re

        text = self._clean_text(text)
        if not text:
            return []
        fallback_size = max(600, min(int(fallback_size or 1400), 2600))
        chunks = []
        heading_stack = []
        current_lines = []
        current_type = "paragraph"
        current_heading = "Document"

        def flush(reason="boundary"):
            nonlocal current_lines, current_type, current_heading
            body = self._clean_text("\n".join(current_lines))
            if not body:
                current_lines = []
                return
            chunks.append({
                "id": len(chunks) + 1,
                "type": current_type,
                "heading_path": " > ".join(heading_stack[-4:]) or current_heading,
                "text": body,
                "length": len(body),
                "reason": reason,
                "signature": self._semantic_signature(body),
            })
            current_lines = []

        for raw in text.splitlines():
            line = raw.strip()
            typ = self._line_type(line)
            if typ == "blank":
                if current_lines and sum(len(x) for x in current_lines) >= fallback_size * 0.55:
                    flush("paragraph boundary")
                continue
            if typ == "heading":
                flush("new heading")
                clean_heading = re.sub(r"\s+", " ", line)[:120]
                level = len(re.match(r"^(\d+(?:\.\d+)*)", clean_heading).group(1).split(".")) if re.match(r"^(\d+(?:\.\d+)*)", clean_heading) else 1
                heading_stack[:] = heading_stack[:max(0, level - 1)]
                heading_stack.append(clean_heading)
                current_heading = clean_heading
                current_type = "section"
                current_lines = [line]
                continue
            if typ in ["table", "equation", "reference", "figure"] and current_type != typ:
                flush(f"switch to {typ}")
                current_type = typ
            elif current_type in ["table", "equation", "reference", "figure"] and typ == "paragraph":
                flush("switch to paragraph")
                current_type = "paragraph"
            current_lines.append(line)
            if sum(len(x) for x in current_lines) >= fallback_size:
                flush("size limit")
        flush("end document")

        if len(chunks) <= 1 and len(text) > fallback_size:
            chunks = []
            for idx, start in enumerate(range(0, len(text), fallback_size), start=1):
                body = text[start:start + fallback_size]
                chunks.append({
                    "id": idx,
                    "type": "fallback_character",
                    "heading_path": "Document",
                    "text": body,
                    "length": len(body),
                    "reason": "fallback character-count",
                    "signature": self._semantic_signature(body),
                })
        return chunks[:120]

    def _tokens(self, text):
        import re

        stop = {"yang", "dan", "atau", "untuk", "dengan", "dari", "pada", "ini", "itu", "the", "and", "for", "from", "with", "about"}
        return [t for t in re.findall(r"[a-zA-Z0-9_]+", (text or "").lower()) if len(t) > 2 and t not in stop]

    def _chunk_score(self, query, chunk, query_vec=None):
        from collections import Counter

        q_terms = set(self._tokens(query))
        terms = Counter(self._tokens(chunk["text"]))
        lexical_raw = sum(terms[t] for t in q_terms)
        lexical = min(1.0, lexical_raw / max(1, len(q_terms)))
        q_sig = self._semantic_signature(query)
        c_sig = chunk.get("signature") or set()
        semantic = (len(q_sig & c_sig) / max(1, len(q_sig | c_sig))) if q_sig and c_sig else 0.0
        vector = self._cosine(query_vec or self._vectorize(query), self._vectorize(chunk["text"])) if self.enable_vector_lite else 0.0
        type_weight = {
            "section": 1.1,
            "paragraph": 1.0,
            "table": 1.35,
            "equation": 1.3,
            "reference": 1.15,
            "figure": 1.1,
            "fallback_character": 0.75,
        }.get(chunk.get("type"), 1.0)
        intent_bonus = 0.0
        q_low = (query or "").lower()
        if any(w in q_low for w in ["tabel", "table", "data", "dataset"]) and chunk.get("type") == "table":
            intent_bonus += 2.0
        if any(w in q_low for w in ["rumus", "formula", "equation", "persamaan"]) and chunk.get("type") == "equation":
            intent_bonus += 2.0
        if any(w in q_low for w in ["referensi", "citation", "sumber", "paper"]) and chunk.get("type") == "reference":
            intent_bonus += 2.0
        meta_ok, meta_bonus = self._metadata_match(chunk)
        if not meta_ok:
            return {"total": -1.0, "keyword": lexical, "vector": vector, "semantic": semantic, "source": 0.0, "confidence": 0.0, "metadata_ok": False}
        src = self._source_metadata(chunk)
        kw_w = max(0, int(self.keyword_weight or 45)) / 100.0
        vec_w = max(0, int(self.vector_weight or 40)) / 100.0
        src_w = max(0, int(self.source_weight or 15)) / 100.0
        evidence_score = (lexical * kw_w * type_weight) + (max(vector, semantic) * vec_w) + (src["source_rank"] * src_w) + (intent_bonus / 10.0) + (meta_bonus / 5.0)
        confidence = max(0.0, min(1.0, evidence_score))
        return {
            "total": evidence_score,
            "keyword": lexical,
            "vector": vector,
            "semantic": semantic,
            "source": src["source_rank"],
            "credibility": src["credibility"],
            "confidence": confidence,
            "metadata_ok": True,
        }

    def _local_rag(self, query, corpus, chunk_size, top_k):
        chunks = self._adaptive_chunks(corpus, int(chunk_size or 1400))
        if not chunks:
            return ""
        query_vec = self._vectorize(query)
        scored = []
        for chunk in chunks:
            scores = self._chunk_score(query, chunk, query_vec)
            if scores["metadata_ok"]:
                scored.append((scores["total"], chunk["id"], chunk, scores))
        if not scored:
            scored = [(0.0, c["id"], c, {"total": 0.0, "keyword": 0.0, "vector": 0.0, "semantic": 0.0, "source": self._source_metadata(c)["source_rank"], "credibility": self._source_metadata(c)["credibility"], "confidence": 0.0, "metadata_ok": True}) for c in chunks]
        scored.sort(key=lambda x: (x[0], -x[1]), reverse=True)
        limit = max(1, int(top_k or 5))
        min_conf = max(0, int(self.min_confidence or 18)) / 100.0
        selected = [(c, s) for score, _, c, s in scored[:limit] if s.get("confidence", 0.0) >= min_conf] or [(c, s) for _, _, c, s in scored[:limit]]
        lines = []
        for rank, (chunk, scores) in enumerate(selected, start=1):
            citation = f"[DBRAG-{chunk['id']}]"
            lines.append(
                "\n".join([
                    f"[Hybrid RAG Evidence {rank}] {citation}",
                    f"Original Chunk ID: {chunk['id']}",
                    f"Type: {chunk['type']}",
                    f"Heading Path: {chunk['heading_path']}",
                    f"Split Reason: {chunk['reason']}",
                    f"Length: {chunk['length']}",
                    f"Keyword Score: {scores['keyword']:.3f}",
                    f"Vector-Lite Score: {scores['vector']:.3f}",
                    f"Semantic-Lite Score: {scores['semantic']:.3f}",
                    f"Source Rank: {scores['source']:.3f}",
                    f"Credibility: {scores.get('credibility', 'Unclassified')}",
                    f"Confidence: {scores['confidence']:.2%}",
                    f"Citation: {citation}",
                    "Text:",
                    chunk["text"],
                ])
            )
        return "\n\n---HYBRID-RAG-EVIDENCE---\n\n".join(lines)

    def _numbers_from_text(self, text):
        import json
        import re

        for match in re.findall(r"\[[^\]]+\]", text or ""):
            try:
                parsed = json.loads(match)
                nums = [float(x) for x in parsed if isinstance(x, (int, float))]
                if len(nums) >= 2:
                    return nums
            except Exception:
                pass
        nums = []
        for token in re.findall(r"[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?", text or ""):
            try:
                nums.append(float(token))
            except Exception:
                pass
        return nums[:500]

    def _numeric_report(self, nums):
        if not nums or len(nums) < 2:
            return "No sufficient numeric dataset detected."
        import statistics

        n = len(nums)
        mean = sum(nums) / n
        std = statistics.stdev(nums)
        return "\n".join([
            f"n = {n}",
            f"sum = {sum(nums):.6f}",
            f"mean = {mean:.6f}",
            f"median = {statistics.median(nums):.6f}",
            f"sample variance = {std ** 2:.6f}",
            f"sample standard deviation = {std:.6f}",
            f"min = {min(nums):.6f}",
            f"max = {max(nums):.6f}",
            f"range = {max(nums) - min(nums):.6f}",
        ])

    def _urls_from_text(self, *texts):
        import re

        seen, urls = set(), []
        for text in texts:
            for url in re.findall(r"https?://[^\s\]\)}>\"']+", text or ""):
                url = url.rstrip(".,;:")
                if url not in seen:
                    seen.add(url)
                    urls.append(url)
        return urls[:max(1, int(self.max_realtime_urls or 8))]

    def _domain(self, url):
        try:
            from urllib.parse import urlparse

            return (urlparse(url).netloc or "").lower().replace("www.", "")
        except Exception:
            return ""

    def _domain_allowed(self, url):
        domain = self._domain(url)
        allowed = [x.strip().lower().replace("www.", "") for x in self._to_text(self.allowed_domains).replace(",", "\n").splitlines() if x.strip()]
        blocked = [x.strip().lower().replace("www.", "") for x in self._to_text(self.blocked_domains).replace(",", "\n").splitlines() if x.strip()]
        if any(b and b in domain for b in blocked):
            return False, f"blocked domain: {domain}"
        if allowed and not any(a in domain for a in allowed):
            return False, f"not in allowed domains: {domain}"
        return True, "allowed"

    def _credibility(self, url):
        u = (url or "").lower()
        high = ["bps.go.id", "bi.go.id", "ojk.go.id", "worldbank.org", "imf.org", "oecd.org", "who.int", "unesco.org", "nasa.gov", "nature.com", "sciencedirect.com", "crossref.org", "cloud.google.com", "ai.google.dev", "learn.microsoft.com", "openai.com", "tensorflow.org", "pytorch.org", "scikit-learn.org", ".edu", ".ac.id", ".go.id", ".gov"]
        medium = ["ourworldindata.org", "arxiv.org", "semanticscholar.org", "kaggle.com", "github.com", "oeis.org"]
        if any(d in u for d in high):
            return "High"
        if any(d in u for d in medium):
            return "Medium-High/Medium; verify primary source or peer-review status."
        if "wikipedia.org" in u:
            return "Low-priority fallback; verify with primary sources."
        return "Unclassified; verify author, institution, date, and cited sources."

    def _source_priority(self, url):
        cred = self._credibility(url)
        if cred == "High":
            return 100
        if cred == "High/Technical":
            return 92
        if cred.startswith("Medium"):
            return 72
        if cred.startswith("Low"):
            return 35
        return 50

    def _extract_html_metadata(self, html, url):
        import re
        import html as html_mod

        def first(pattern):
            m = re.search(pattern, html or "", re.I | re.S)
            return html_mod.unescape(m.group(1).strip()) if m else ""

        title = first(r"<title[^>]*>(.*?)</title>")
        desc = first(r'<meta[^>]+(?:name|property)=["\'](?:description|og:description)["\'][^>]+content=["\'](.*?)["\']')
        if not desc:
            desc = first(r'<meta[^>]+content=["\'](.*?)["\'][^>]+(?:name|property)=["\'](?:description|og:description)["\']')
        author = first(r'<meta[^>]+name=["\']author["\'][^>]+content=["\'](.*?)["\']')
        published = first(r'<meta[^>]+(?:name|property)=["\'](?:article:published_time|date|dc.date)["\'][^>]+content=["\'](.*?)["\']')
        canonical = first(r'<link[^>]+rel=["\']canonical["\'][^>]+href=["\'](.*?)["\']') or url
        return {
            "title": title[:180],
            "description": desc[:300],
            "author": author[:120],
            "published": published[:80],
            "canonical": canonical,
            "domain": self._domain(url),
        }

    def _clean_article_html(self, raw):
        import re
        import html

        text = raw or ""
        text = re.sub(r"<script[\s\S]*?</script>", " ", text, flags=re.I)
        text = re.sub(r"<style[\s\S]*?</style>", " ", text, flags=re.I)
        article_match = re.search(r"<article[^>]*>([\s\S]*?)</article>", text, flags=re.I)
        if article_match:
            text = article_match.group(1)
        else:
            main_match = re.search(r"<main[^>]*>([\s\S]*?)</main>", text, flags=re.I)
            if main_match:
                text = main_match.group(1)
        text = re.sub(r"<(br|p|div|li|h[1-6]|tr|section|article)[^>]*>", "\n", text, flags=re.I)
        text = re.sub(r"<[^>]+>", " ", text)
        text = html.unescape(text)
        return self._clean_text(text)

    def _fetch_url(self, url, max_chars):
        allowed, reason = self._domain_allowed(url)
        if not allowed:
            return {"ok": False, "url": url, "reason": reason, "metadata": {"domain": self._domain(url)}, "text": "", "citation": "", "credibility": self._credibility(url), "priority": self._source_priority(url)}
        try:
            from urllib.request import Request, urlopen

            req = Request(url, headers={"User-Agent": "DataBrainAI/1.6 RealtimeRetrieval"})
            with urlopen(req, timeout=8) as response:
                raw = response.read(max_chars * 4)
                final_url = getattr(response, "url", url)
            html = raw.decode("utf-8", errors="ignore")
            metadata = self._extract_html_metadata(html, final_url)
            text = self._clean_article_html(html)[:max_chars]
            citation = f"[WEB-{abs(hash(metadata.get('canonical') or final_url)) % 100000}]"
            return {
                "ok": bool(text),
                "url": final_url,
                "reason": "fetched",
                "metadata": metadata,
                "text": text,
                "citation": citation,
                "credibility": self._credibility(final_url),
                "priority": self._source_priority(final_url),
            }
        except Exception as exc:
            return {"ok": False, "url": url, "reason": f"[FETCH FAILED] {type(exc).__name__}: {exc}", "metadata": {"domain": self._domain(url)}, "text": "", "citation": "", "credibility": self._credibility(url), "priority": self._source_priority(url)}

    def _file_context(self, message, max_chars):
        items = []
        items.extend(self._message_files(message))
        items.extend(self._override_items())
        if not self.enable_file_reading:
            return "", [], "File reading disabled."
        if not items:
            return "", [], "No uploaded file or File Path Override provided."
        blocks, recoveries = [], []
        budget = max(1800, max_chars // max(1, len(items)))
        for idx, item in enumerate(items, start=1):
            result = self._read_item(item, budget)
            if result["text"]:
                structure = self._structure_report(result["text"])
                blocks.append("\n".join([
                    f"[Document {idx}]",
                    f"Path/Source: {result['path']}",
                    f"Extraction method: {result['method']}",
                    f"Language hint: {self._language_hint(result['text'])}",
                    f"Metadata/Structure: headings={len(structure['headings'])}, tables={len(structure['tables'])}, figures={len(structure['figures'])}, equations={len(structure['equations'])}, references={len(structure['references'])}",
                    "Auto Summary:",
                    self._summary(result["text"]),
                    "Extracted Text:",
                    result["text"],
                ]))
            else:
                recoveries.append(f"[Document {idx}] {result['path']} :: {result['method']} :: " + " | ".join(result["recoveries"]))
            recoveries.extend(result["recoveries"])
        return "\n\n".join(blocks), recoveries, "processed"


    def _infer_persona(self, text):
        low = (text or "").lower()
        if any(w in low for w in ["dataset", "csv", "dataframe", "kolom", "variabel"]):
            return "Data Scientist"
        if any(w in low for w in ["paper", "jurnal", "metodologi", "hipotesis", "research question"]):
            return "Research Professor"
        if any(w in low for w in ["kode", "python", "javascript", "api", "bug", "stack trace"]):
            return "Software Engineer"
        if any(w in low for w in ["statistik", "regresi", "uji", "p-value", "variance"]):
            return "Statistician"
        if any(w in low for w in ["machine learning", "model", "training", "overfitting", "feature"]):
            return "ML Engineer"
        if any(w in low for w in ["database", "sql", "pipeline", "etl", "schema"]):
            return "Data Engineer"
        if any(w in low for w in ["arsitektur", "deployment", "integrasi", "system design"]):
            return "System Architect"
        return "Research/Data Assistant"

    def _evidence_sufficiency(self, working_context, url_blocks, file_text):
        score = 0
        reasons = []
        if working_context and len(working_context) > 500:
            score += 45; reasons.append("working context tersedia")
        if url_blocks:
            score += 25; reasons.append("URL evidence tersedia")
        if file_text:
            score += 20; reasons.append("dokumen/file terbaca")
        if "[FETCH FAILED]" in (working_context or ""):
            score -= 15; reasons.append("sebagian fetch gagal")
        score = max(0, min(100, score))
        status = "cukup" if score >= 55 else "belum cukup"
        return score, status, "; ".join(reasons) or "bukti terbatas"

    def _reasoning_protocol(self, persona, evidence_score, evidence_status):
        return "\n".join([
            "Reasoning Pipeline:",
            "1. Understand: pahami intent, persona, dan batasan user.",
            "2. Analyze: identifikasi data, variabel, konteks, dan pertanyaan inti.",
            "3. Search/Retrieve: gunakan file, URL, RAG slot, dan trusted context.",
            "4. Rank Evidence: gunakan confidence, credibility, metadata, dan citation.",
            "5. Reason: pisahkan Fakta, Inferensi, Asumsi, Hipotesis, Rekomendasi.",
            "6. Cross-check: jangan gunakan klaim yang tidak didukung evidence.",
            "7. Self-Verify: jika bukti belum cukup, katakan tidak bisa memverifikasi.",
            f"Detected Persona: {persona}",
            f"Evidence Sufficiency: {evidence_status} ({evidence_score}/100)",
        ])


    def _rank_memory_lines(self, text, query):
        q = set(self._tokens(query))
        lines = [x.strip() for x in (text or "").splitlines() if x.strip()]
        scored = []
        for i, line in enumerate(lines):
            score = len(q & set(self._tokens(line)))
            scored.append((score, -i, line))
        scored.sort(reverse=True)
        return "\n".join(line for score, _, line in scored[:30] if score > 0) or "\n".join(lines[-20:])

    def _memory_context(self, user_text):
        parts = []
        conv = self._rank_memory_lines(self._to_text(self.conversation_memory), user_text)
        work = self._to_text(self.working_memory).strip()
        know = self._to_text(self.knowledge_memory).strip()
        hist = self._to_text(self.history_ranking_keywords).strip()
        if conv: parts.append("[Conversation Memory]\n" + conv)
        if work: parts.append("[Working Memory]\n" + work)
        if know: parts.append("[Knowledge Memory]\n" + know)
        if hist: parts.append("[History Ranking Keywords]\n" + hist)
        return "\n\n".join(parts)

    def _compress_text(self, text, target_chars=None):
        target = int(target_chars or self.context_compression_target or 12000)
        text = self._clean_text(text)
        if len(text) <= target:
            return text
        head = text[: target // 3]
        tail = text[-target // 3:]
        middle = text[target // 3: -target // 3]
        ranked = self._local_rag("", middle, 1200, 4) if middle else ""
        return self._clean_text(head + "\n\n[Context compressed middle]\n" + ranked + "\n\n" + tail)[:target]

    def build_prompt(self) -> Message:
        message = self.user_message
        user_text = self._to_text(message).strip()
        manual = self._to_text(self.manual_context).strip()
        rag_slot = self._to_text(self.rag_context).strip()
        policy = self._to_text(self.agent_policy).strip()
        file_text, file_recoveries, file_status = self._file_context(message, int(self.max_file_chars or 24000))

        url_blocks, source_lines, url_corpus = [], [], []
        if self.enable_url_fetch:
            url_text = "\n".join([user_text, self._to_text(self.realtime_source_urls), self._to_text(self.trusted_source_pack)])
            fetched = [self._fetch_url(url, int(self.max_url_chars or 3000)) for url in self._urls_from_text(url_text)]
            fetched.sort(key=lambda item: item.get("priority", 0), reverse=bool(self.prefer_official_sources))
            for idx, item in enumerate(fetched, start=1):
                meta = item.get("metadata", {})
                citation = item.get("citation") or f"[WEB-SKIPPED-{idx}]"
                source_lines.append(
                    f"{idx}. {citation} {item.get('url')} | Domain: {meta.get('domain', '')} | Credibility: {item.get('credibility')} | Priority: {item.get('priority')} | Status: {item.get('reason')}"
                )
                if item.get("ok"):
                    block = "\n".join([
                        f"[Realtime Source {idx}] {citation}",
                        f"URL: {item.get('url')}",
                        f"Canonical: {meta.get('canonical', item.get('url'))}",
                        f"Domain: {meta.get('domain', '')}",
                        f"Title: {meta.get('title', '')}",
                        f"Description: {meta.get('description', '')}",
                        f"Author: {meta.get('author', '')}",
                        f"Published: {meta.get('published', '')}",
                        f"Credibility: {item.get('credibility')}",
                        f"Priority: {item.get('priority')}",
                        f"Citation: {citation}",
                        "Cleaned Article Text:",
                        item.get("text", ""),
                    ])
                    url_blocks.append(block)
                    url_corpus.append(block)
                else:
                    url_blocks.append(f"[Realtime Source {idx}] {citation}\nURL: {item.get('url')}\nStatus: {item.get('reason')}\nCredibility: {item.get('credibility')}")

        memory_context = self._memory_context(user_text)
        corpus = "\n\n".join(x for x in [file_text, manual, rag_slot, memory_context, "\n\n".join(url_corpus)] if x.strip())
        corpus = self._compress_text(corpus, self.context_compression_target)
        if self.enable_context_compression:
            corpus = self._compress_text(corpus, self.max_working_context_chars)
        working_context = self._local_rag(user_text, corpus, int(self.chunk_size or 1400), int(self.top_k_chunks or 5)) if self.enable_local_rag else corpus[:int(self.max_working_context_chars or 10000)]
        nums = self._numbers_from_text("\n".join([user_text, corpus])) if self.auto_numeric else []

        recovery = []
        if file_recoveries:
            recovery.extend([x for x in file_recoveries if x])
            recovery.append("Layered recovery order: direct extraction -> OCR if available -> ZIP/OOXML parser -> embedded bytes/text -> File Path Override -> Manual Context / OCR Paste.")
        if file_status.startswith("No uploaded"):
            recovery.append("No file was available. Use upload, File Path Override, or Manual Context / OCR Paste.")

        persona = self._infer_persona(user_text + "\n" + corpus)
        evidence_score, evidence_status, evidence_reasons = self._evidence_sufficiency(working_context, url_blocks, file_text)
        reasoning_protocol = self._reasoning_protocol(persona, evidence_score, evidence_status)

        blocks = [
            "DATABRAIN UPDATE VERSION 2.2 TASK 11 INTEGRATION DEPLOYMENT OUTPUT",
            "PIPELINE: URL discovery -> domain filter -> source priority -> fetch -> page/article cleaning -> metadata extraction -> citation generation -> hybrid RAG working context.",
            "USER REQUEST:\n" + (user_text or "No user text received."),
            "AGENT POLICY:\n" + policy,
            "DEPLOYMENT MODE:\n" + self._to_text(self.deployment_mode),
            "INTEGRATION TARGETS:\n" + self._to_text(self.integration_targets),
            "CLASSIFIER PROMPT:\n" + self._to_text(self.classifier_prompt),
            "SAFETY PROMPT:\n" + self._to_text(self.safety_prompt),
            "RAG PROMPT:\n" + self._to_text(self.rag_prompt),
            "FINAL ANSWER PROMPT:\n" + self._to_text(self.final_answer_prompt),
            "RECOVERY PROMPT:\n" + self._to_text(self.recovery_prompt),
            "OUTPUT FORMATTER PROMPT:\n" + self._to_text(self.output_formatter_prompt),
            "MEMORY ARCHITECTURE:\nConversation Memory + Working Memory + Knowledge Memory + Context Compression + History Ranking are active when fields are filled.",
            "REASONING / ANTI-HALLUCINATION PROTOCOL:\n" + reasoning_protocol + "\nEvidence reasons: " + evidence_reasons,
        ]
        if file_text:
            blocks.append("DOCUMENT WORKING MEMORY:\n" + file_text[:9000])
        if working_context:
            blocks.append("ADAPTIVE WORKING CONTEXT / LOCAL RAG:\n" + working_context)
        if url_blocks:
            blocks.append("REALTIME URL CONTEXT:\n" + "\n\n".join(url_blocks))
        blocks.append("NUMERICAL PRE-ANALYSIS:\n" + self._numeric_report(nums))
        if source_lines:
            blocks.append("SOURCE CREDIBILITY REGISTER:\n" + "\n".join(source_lines))
        if recovery:
            blocks.append("FILE PARSER RECOVERY GUIDANCE:\n" + "\n".join(f"- {x}" for x in recovery[:20]))
        blocks.append(
            "ANSWER CONTRACT:\n"
            "1. If readable document text exists, analyze it directly.\n"
            "2. If a file failed, do not fabricate contents; explain exact recovery steps.\n"
            "3. Separate facts, inference, assumptions, and recommendations when evidence is mixed.\n"
            "4. For documents, mention detected language, structure, tables/figures/equations/references if relevant.\n"
            "5. Separate Fakta, Inferensi, Asumsi, Hipotesis, and Rekomendasi.\n"
            "6. If evidence sufficiency is belum cukup, explicitly say: saya tidak bisa memverifikasi ini dari bukti yang tersedia.\n"
            "7. Final output sections are mandatory: Executive Summary, Reasoning, Evidence, Analysis, Confidence, Assumptions, Recommendation/Next Action, References.\n"
            "8. End with 'Saran Perbaikan Jika Output Belum Sesuai'."
        )
        text = "\n\n---\n\n".join(blocks)
        self.status = text
        return Message(text=text)
